[ {
  "message" : "<div>\n<div role=\"dialog\" aria-labelledby=\"modalHeading-l1i01oni97od-1082\">\n<div role=\"document\">\n<div>\n<div>\n<div>\n<div>\n<div><span style=\"font-size: 12pt;\">Do you want to update scoping guide?</span></div>\n</div>\n<div>&nbsp;</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>",
  "comment" : ""
}, {
  "message" : "<p style=\"text-align: left;\"><span style=\"font-size: 11pt;\">Our migration process ensures a seamless transfer of your data, configurations, and workflows to ServiceNow. From mapping your data structures to system integration, we guide you every step of the way to ensure business continuity and enhance your SAM experience. </span></p>",
  "comment" : ""
}, {
  "message" : "<p><span style=\"font-family: verdana, geneva; font-size: 12pt;\">Welcome to ServiceNow SAM Implementation!</span></p>\n<p><span style=\"font-size: 12pt;\">Let&rsquo;s begin by understanding your current setup to customize the experience. </span></p>",
  "comment" : ""
}, {
  "message" : "<p><span style=\"font-size: 11pt;\">With ServiceNow, you can effectively manage your software lifecycle while driving cost savings and maximizing the value of your IT investments. we&rsquo;ll guide you through every step to maintain business continuity and optimize your SAM experience.&nbsp;</span></p>",
